  action: z.enum(['accept', 'dismiss']),
  promptText: z.string().optional(), // Text to enter for prompt() dialogs
  tab_id: z.number().optional()
});
```

### 2. Extension Background (packages/extension/src/background.ts)
```typescript
async function handleDialog(tabId: number, action: 'accept' | 'dismiss', promptText?: string) {
  const target = { tabId };

  // Debugger should already be attached for inspection
  // If not, attach temporarily
  let wasAttached = false;
  try {
    await chrome.debugger.attach(target, '1.3');
    wasAttached = true;
  } catch (e) {
    // Already attached, that's fine
  }

  try {
    await chrome.debugger.sendCommand(target, 'Page.handleJavaScriptDialog', {
      accept: action === 'accept',
      promptText
    });
  } finally {
    if (wasAttached) {
      await chrome.debugger.detach(target);
    }
  }
}
```

