Support pressing special keys like Arrow keys, Enter, Escape, Tab that aren't text input.

## Why
Navigation with arrow keys, submitting with Enter, closing dialogs with Escape, tab navigation - common automation needs.

## YetiBrowser Reference
File: /Users/btraut/Downloads/yetibrowser-mcp-main/extensions/shared/src/background/index.ts
- Function: pressKey
- Supports standard key names: ArrowUp, ArrowDown, ArrowLeft, ArrowRight, Enter, Escape, Tab, Backspace, Delete, Home, End, PageUp, PageDown

## Implementation

### 1. Schema (packages/shared/src/schemas.ts)
```typescript
const KeyPressInputSchema = z.object({
  key: z.string(), // Key name per KeyboardEvent.key spec
  modifiers: z.object({
    ctrl: z.boolean().optional(),
    alt: z.boolean().optional(),
    shift: z.boolean().optional(),
    meta: z.boolean().optional()
  }).optional(),
  tab_id: z.number().optional()
});
```

### 2. Content Script (packages/extension/src/content.ts)
```typescript
function pressKey(key: string, modifiers?: { ctrl?: boolean; alt?: boolean; shift?: boolean; meta?: boolean }) {
  const target = document.activeElement || document.body;

  const eventInit: KeyboardEventInit = {
    key,
    code: keyToCode(key), // e.g., 'Enter' -> 'Enter', 'ArrowUp' -> 'ArrowUp'
    bubbles: true,
    cancelable: true,
    ctrlKey: modifiers?.ctrl ?? false,
    altKey: modifiers?.alt ?? false,
    shiftKey: modifiers?.shift ?? false,
    metaKey: modifiers?.meta ?? false
  };

  target.dispatchEvent(new KeyboardEvent('keydown', eventInit));
  target.dispatchEvent(new KeyboardEvent('keyup', eventInit));
}

function keyToCode(key: string): string {
  const codeMap: Record<string, string> = {
    'Enter': 'Enter',
    'Tab': 'Tab',
    'Escape': 'Escape',
    'Backspace': 'Backspace',
    'Delete': 'Delete',
    'ArrowUp': 'ArrowUp',
    'ArrowDown': 'ArrowDown',
    'ArrowLeft': 'ArrowLeft',
    'ArrowRight': 'ArrowRight',
    'Home': 'Home',
    'End': 'End',
    'PageUp': 'PageUp',
    'PageDown': 'PageDown',
    ' ': 'Space'
  };
  return codeMap[key] || `Key${key.toUpperCase()}`;
}
```

